// ── DB Insert ──────────────────────────────────────────────────────────────────
async function seed() {
  const connectionString = process.env.DATABASE_URL || "";
  if (!connectionString) {
    console.error("DATABASE_URL not set");
    process.exit(1);
  }

  const client = new Client({
    connectionString,
    ssl: connectionString.includes("localhost") || connectionString.includes("127.0.0.1")
      ? false
      : { rejectUnauthorized: false },
  });

  await client.connect();
  console.log(`Connected. Seeding ${QUESTIONS.length} trivia questions...`);

  // Ensure unique constraint exists so ON CONFLICT works on re-runs
  await client.query(`
    DO $$
    BEGIN
      IF NOT EXISTS (
        SELECT 1 FROM pg_constraint WHERE conname = 'uq_trivia_question'
      ) THEN
        ALTER TABLE trivia_questions ADD CONSTRAINT uq_trivia_question UNIQUE (question);
      END IF;
    END
    $$;
  `);

  let inserted = 0;
  let skipped = 0;

  for (const q of QUESTIONS) {
    const res = await client.query(
      `INSERT INTO trivia_questions (question, question_ml, options, options_ml, correct_index, difficulty, explanation, explanation_ml, active)
       VALUES ($1, $2, $3, $4, $5, $6, $7, $8, true)
       ON CONFLICT (question)
       DO UPDATE SET
         question_ml = EXCLUDED.question_ml,
         options_ml = EXCLUDED.options_ml,
         explanation_ml = EXCLUDED.explanation_ml`,
      [
        q.question,
        q.question_ml || '',
        JSON.stringify(q.options),
        JSON.stringify(q.options_ml || []),
        q.correct_index,
        q.difficulty,
        q.explanation,
        q.explanation_ml || '',
      ]
    );
    if ((res.rowCount ?? 0) > 0) inserted++;
    else skipped++;
  }

  await client.end();

  console.log(`✅ Done. Inserted: ${inserted}, Skipped (already exist): ${skipped}`);
  console.log(`Total questions now in DB: will be ${inserted} new + existing.`);
  console.log(`\nTo reach 2000 questions, add more entries to the QUESTIONS array and re-run this script.`);
}

seed().catch((err) => {
  console.error("Seed failed:", err);
  process.exit(1);
});
